  "definitions": [
    {
      "term": {
        "text": "implicit casting",
        "refs": ["Q0000"]
      },
      "definition_text": {
        "text": "implicit casting happens whenever you're not going to lose data; there is no chance for data loss",
        "refs": ["Q0000"]
      },
      "context": null
    },
    {
      "term": {
        "text": "explicit casting",
        "refs": ["Q0000", "Q0001"]
      },
      "definition_text": {
        "text": "explicit casting converts a value to a specified type, such as casting a floating‑point number to an integer to discard the fractional part",
        "refs": ["Q0000", "Q0001"]
      },
      "context": null
    },
    {
      "term": {
        "text": "wrapper class",
        "refs": ["Q0002"]
      },
      "definition_text": {
        "text": "a reference type that provides methods for converting between strings and primitive types, e.g., java.lang.Integer for the int primitive",
        "refs": ["Q0002"]
      },
      "context": null
    }
  ],
  "facts": [
    {
      "fact_text": {
        "text": "explicit casting can only happen between compatible numeric types; you cannot cast a string to a number directly",
        "refs": ["Q0001"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "the Integer class provides a parseInt method that takes a string and returns an int",
        "refs": ["Q0002"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "the Short class provides a parseShort method that takes a string and returns a short",
        "refs": ["Q0002"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "user input from UI components is typically received as strings, requiring conversion to numeric types for arithmetic",
        "refs": ["Q0004"]
      },
      "fact_type": null
    }
  ],
  "examples": [
    {
      "exemplifies": {
        "text": "casting a floating‑point value 1.1 to an int results in 1",
        "refs": ["Q0000"]
      },
      "example_text": {
        "text": "int y = (int)1.1; // y becomes 1",
        "refs": ["Q0000"]
      },
      "example_type": null
    },
    {
      "exemplifies": {
        "text": "parsing a string \"1\" to an int using Integer.parseInt",
        "refs": ["Q0003"]
      },
      "example_text": {
        "text": "int x = Integer.parseInt(\"1\");",
        "refs": ["Q0003"]
      },
      "example_type": null
    }
  ],
